//! Generated Protocol Buffer code for the RustyStore inter-node protocol.
//!
//! This module re-exports the code generated by `tonic-build` from
//! `proto/storage.proto`. See that file for the canonical message/service
//! definitions.
//!
//! The generated types live under `proto::storage::` and are re-exported here
//! for convenient use across the workspace.

pub mod storage {
    #![allow(clippy::all, non_snake_case, unused)]
    include!(concat!(env!("OUT_DIR"), "/storage.rs"));
}

pub use storage::{
    chunk_service_client::ChunkServiceClient,
    chunk_service_server::{ChunkService, ChunkServiceServer},
    cluster_service_client::ClusterServiceClient,
    cluster_service_server::{ClusterService, ClusterServiceServer},
    node_service_client::NodeServiceClient,
    node_service_server::{NodeService, NodeServiceServer},
};
